from solution import find_Average_Of_Cube
import inspect


def test_issue_n1():
    """Average of cubes of first 1 natural numbers is 1."""
    assert find_Average_Of_Cube(1) == 1.0  # 1 / 1 = 1


def test_issue_n2_example():
    """Average of cubes of first 2 natural numbers is 4.5."""
    assert find_Average_Of_Cube(2) == 4.5  # (1 + 8) / 2 = 4.5


def test_issue_n3():
    """Average of cubes of first 3 natural numbers is 12."""
    assert find_Average_Of_Cube(3) == 12.0  # (1 + 8 + 27) / 3 = 36 / 3 = 12


def test_issue_n4():
    """Average of cubes of first 4 natural numbers is 25."""
    assert find_Average_Of_Cube(4) == 25.0  # (1 + 8 + 27 + 64) / 4 = 100 / 4 = 25


