    """Average of cubes of first 6 natural numbers is 73.5."""
    assert find_Average_Of_Cube(6) == 73.5  # (1 + 8 + 27 + 64 + 125 + 216) / 6 = 441 / 6 = 73.5


def test_issue_n7():
    """Average of cubes of first 7 natural numbers is 112."""
    assert find_Average_Of_Cube(7) == 112.0  # (441 + 343) / 7 = 784 / 7 = 112


