    """Average of cubes of first 10 natural numbers is 302.5."""
    assert find_Average_Of_Cube(10) == 302.5  # 55*55 / 10 = 3025 / 10 = 302.5


def test_issue_n20():
    """Average of cubes of first 20 natural numbers is 2205."""
    assert find_Average_Of_Cube(20) == 2205.0  # 210*210 / 20 = 44100 / 20 = 2205


