    """Average of cubes of first 100 natural numbers is 255025."""
    assert find_Average_Of_Cube(100) == 255025.0  # 5050*5050 / 100 = 25502500 / 100 = 255025


def test_contract_single_parameter():
    """Public interface shows find_Average_Of_Cube(n) takes one argument."""
    assert len(inspect.signature(find_Average_Of_Cube).parameters) == 1  # expects exactly 1 parameter


def test_contract_callable():
    """Public interface shows solution.find_Average_Of_Cube is a function."""
    assert callable(find_Average_Of_Cube) == True  # callable() is True for a function
